@prefix fis: <http://example.org/onto/securities#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities>
    a owl:Ontology ;
    rdfs:label "Securities and Financial Instruments Ontology"@en ;
    rdfs:comment "An ontology formalizing securities, derivatives, debt and equity instruments, market entities, and their structural properties based on financial market standards and regulatory authorities."@en .

#################################################################
#    Annotation Properties
#################################################################

rdfs:label a owl:AnnotationProperty .
rdfs:comment a owl:AnnotationProperty .

#################################################################
#    Object Properties
#################################################################

fis:hasIssuer a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:label "has issuer"@en ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range fis:LegalEntity ;
    owl:inverseOf fis:isIssuerOf .

fis:isIssuerOf a owl:ObjectProperty ;
    rdfs:label "is issuer of"@en ;
    rdfs:domain fis:LegalEntity ;
    rdfs:range fis:FinancialInstrument ;
    owl:inverseOf fis:hasIssuer .

fis:hasHolder a owl:ObjectProperty ;
    rdfs:label "has holder"@en ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range fis:Agent ;
    owl:inverseOf fis:isHolderOf .

fis:isHolderOf a owl:ObjectProperty ;
    rdfs:label "is holder of"@en ;
    rdfs:domain fis:Agent ;
    rdfs:range fis:FinancialInstrument ;
    owl:inverseOf fis:hasHolder .

fis:hasUnderlying a owl:ObjectProperty ;
    rdfs:label "has underlying"@en ;
    rdfs:domain fis:Derivative ;
    rdfs:range fis:UnderlyingItem ;
    owl:inverseOf fis:isUnderlyingOf .

fis:isUnderlyingOf a owl:ObjectProperty ;
    rdfs:label "is underlying of"@en ;
    rdfs:domain fis:UnderlyingItem ;
    rdfs:range fis:Derivative ;
    owl:inverseOf fis:hasUnderlying .

fis:hasCollateral a owl:ObjectProperty ;
    rdfs:label "has collateral"@en ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range fis:Asset ;
    owl:inverseOf fis:isCollateralOf .

fis:isCollateralOf a owl:ObjectProperty ;
    rdfs:label "is collateral of"@en ;
    rdfs:domain fis:Asset ;
    rdfs:range fis:DebtSecurity ;
    owl:inverseOf fis:hasCollateral .

fis:hasEmbeddedOption a owl:ObjectProperty ;
    rdfs:label "has embedded option"@en ;
    rdfs:domain fis:Bond ;
    rdfs:range fis:Option ;
    owl:inverseOf fis:isEmbeddedOptionOf .

fis:isEmbeddedOptionOf a owl:ObjectProperty ;
    rdfs:label "is embedded option of"@en ;
    rdfs:domain fis:Option ;
    rdfs:range fis:Bond ;
    owl:inverseOf fis:hasEmbeddedOption .

fis:hasConversionTarget a owl:ObjectProperty ;
    rdfs:label "has conversion target"@en ;
    rdfs:domain fis:HybridSecurity ;
    rdfs:range fis:CommonStock ;
    owl:inverseOf fis:isConversionTargetOf .

fis:isConversionTargetOf a owl:ObjectProperty ;
    rdfs:label "is conversion target of"@en ;
    rdfs:domain fis:CommonStock ;
    rdfs:range fis:HybridSecurity ;
    owl:inverseOf fis:hasConversionTarget .

fis:hasTradingVenue a owl:ObjectProperty ;
    rdfs:label "has trading venue"@en ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range fis:TradingVenue ;
    owl:inverseOf fis:isTradingVenueOf .

fis:isTradingVenueOf a owl:ObjectProperty ;
    rdfs:label "is trading venue of"@en ;
    rdfs:domain fis:TradingVenue ;
    rdfs:range fis:FinancialInstrument ;
    owl:inverseOf fis:hasTradingVenue .

fis:hasReferenceEntity a owl:ObjectProperty ;
    rdfs:label "has reference entity"@en ;
    rdfs:domain fis:CreditDerivative ;
    rdfs:range fis:LegalEntity ;
    owl:inverseOf fis:isReferenceEntityOf .

fis:isReferenceEntityOf a owl:ObjectProperty ;
    rdfs:label "is reference entity of"@en ;
    rdfs:domain fis:LegalEntity ;
    rdfs:range fis:CreditDerivative ;
    owl:inverseOf fis:hasReferenceEntity .

fis:hasPortfolio a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:label "has portfolio"@en ;
    rdfs:domain fis:InvestmentFund ;
    rdfs:range fis:Portfolio ;
    owl:inverseOf fis:isPortfolioOf .

fis:isPortfolioOf a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:label "is portfolio of"@en ;
    rdfs:domain fis:Portfolio ;
    rdfs:range fis:InvestmentFund ;
    owl:inverseOf fis:hasPortfolio .

fis:hasTranche a owl:ObjectProperty ;
    rdfs:label "has tranche"@en ;
    rdfs:domain fis:AssetBackedSecurity ;
    rdfs:range fis:Tranche ;
    owl:inverseOf fis:isTrancheOf .

fis:isTrancheOf a owl:ObjectProperty ;
    rdfs:label "is tranche of"@en ;
    rdfs:domain fis:Tranche ;
    rdfs:range fis:AssetBackedSecurity ;
    owl:inverseOf fis:hasTranche .

#################################################################
#    Data Properties
#################################################################

fis:hasMaturityDate a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has maturity date"@en ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range xsd:date .

fis:hasMaturityTermInDays a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has maturity term in days"@en ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range xsd:integer .

fis:hasFaceValue a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has face value"@en ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range xsd:decimal .

fis:hasParValue a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has par value"@en ;
    rdfs:domain fis:Security ;
    rdfs:range xsd:decimal .

fis:hasCouponRate a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has coupon rate"@en ;
    rdfs:domain fis:Bond ;
    rdfs:range xsd:decimal .

fis:hasStrikePrice a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has strike price"@en ;
    rdfs:domain fis:Option ;
    rdfs:range xsd:decimal .

fis:hasConversionPrice a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has conversion price"@en ;
    rdfs:domain fis:HybridSecurity ;
    rdfs:range xsd:decimal .

fis:hasConversionRatio a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has conversion ratio"@en ;
    rdfs:domain fis:HybridSecurity ;
    rdfs:range xsd:decimal .

fis:hasNotionalAmount a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has notional amount"@en ;
    rdfs:domain fis:Derivative ;
    rdfs:range xsd:decimal .

fis:hasExpirationDate a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has expiration date"@en ;
    rdfs:domain fis:Derivative ;
    rdfs:range xsd:date .

fis:hasDividendRate a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has dividend rate"@en ;
    rdfs:domain fis:PreferredStock ;
    rdfs:range xsd:decimal .

fis:hasInternationalSecuritiesIdentificationNumber a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has ISIN"@en ;
    rdfs:domain fis:Security ;
    rdfs:range xsd:string .

#################################################################
#    Top-Level Taxonomy
#################################################################

fis:FinancialInstrument a owl:Class ;
    rdfs:label "Financial Instrument"@en ;
    rdfs:comment "A monetary contract between parties that gives rise to a financial asset of one entity and a financial liability or equity instrument of another entity."@en .

fis:Asset a owl:Class ;
    rdfs:label "Asset"@en ;
    rdfs:comment "A resource controlled by an entity as a result of past events from which future economic benefits are expected to flow."@en .

fis:UnderlyingItem a owl:Class ;
    rdfs:label "Underlying Item"@en ;
    rdfs:comment "An asset, index, rate, or event that forms the underlying reference for a derivative contract."@en .

fis:Asset rdfs:subClassOf fis:UnderlyingItem .

fis:Index a owl:Class ;
    rdfs:subClassOf fis:UnderlyingItem ;
    rdfs:label "Index"@en .

fis:StockIndex a owl:Class ;
    rdfs:subClassOf fis:Index ;
    rdfs:label "Stock Index"@en .

fis:InterestRate a owl:Class ;
    rdfs:subClassOf fis:UnderlyingItem ;
    rdfs:label "Interest Rate"@en .

fis:Commodity a owl:Class ;
    rdfs:subClassOf fis:Asset ;
    rdfs:label "Commodity"@en .

fis:Portfolio a owl:Class ;
    rdfs:label "Portfolio"@en ;
    rdfs:comment "A collection of financial assets, such as stocks, bonds, and money market instruments, held by an investor or fund."@en .

fis:Tranche a owl:Class ;
    rdfs:label "Tranche"@en ;
    rdfs:comment "A slice or class of structured securities offering a distinct level of risk, seniority, and return."@en .

fis:Agent a owl:Class ;
    rdfs:label "Agent"@en .

fis:LegalEntity a owl:Class ;
    rdfs:subClassOf fis:Agent ;
    rdfs:label "Legal Entity"@en .

fis:Person a owl:Class ;
    rdfs:subClassOf fis:Agent ;
    rdfs:label "Person"@en .

fis:Corporation a owl:Class ;
    rdfs:subClassOf fis:LegalEntity ;
    rdfs:label "Corporation"@en .

fis:Government a owl:Class ;
    rdfs:subClassOf fis:LegalEntity ;
    rdfs:label "Government"@en .

fis:SovereignGovernment a owl:Class ;
    rdfs:subClassOf fis:Government ;
    rdfs:label "Sovereign Government"@en .

fis:LocalGovernment a owl:Class ;
    rdfs:subClassOf fis:Government ;
    rdfs:label "Local Government"@en, "Municipality"@en .

fis:SupranationalOrganization a owl:Class ;
    rdfs:subClassOf fis:LegalEntity ;
    rdfs:label "Supranational Organization"@en .

fis:FinancialInstitution a owl:Class ;
    rdfs:subClassOf fis:Corporation ;
    rdfs:label "Financial Institution"@en .

fis:Bank a owl:Class ;
    rdfs:subClassOf fis:FinancialInstitution ;
    rdfs:label "Bank"@en, "Credit Institution"@en .

fis:CentralBank a owl:Class ;
    rdfs:subClassOf fis:FinancialInstitution ;
    rdfs:label "Central Bank"@en .

fis:ClearingHouse a owl:Class ;
    rdfs:subClassOf fis:FinancialInstitution ;
    rdfs:label "Clearing House"@en .

fis:Investor a owl:Class ;
    rdfs:subClassOf fis:Agent ;
    rdfs:label "Investor"@en .

fis:RetailInvestor a owl:Class ;
    rdfs:subClassOf fis:Investor ;
    rdfs:label "Retail Investor"@en .

fis:InstitutionalInvestor a owl:Class ;
    rdfs:subClassOf fis:Investor ;
    rdfs:label "Institutional Investor"@en .

fis:Shareholder a owl:Class ;
    rdfs:subClassOf fis:Investor ;
    rdfs:label "Shareholder"@en, "Stockholder"@en .

fis:Bondholder a owl:Class ;
    rdfs:subClassOf fis:Investor ;
    rdfs:label "Bondholder"@en .

fis:TradingVenue a owl:Class ;
    rdfs:label "Trading Venue"@en .

fis:StockExchange a owl:Class ;
    rdfs:subClassOf fis:TradingVenue ;
    rdfs:label "Stock Exchange"@en .

fis:FuturesExchange a owl:Class ;
    rdfs:subClassOf fis:TradingVenue ;
    rdfs:label "Futures Exchange"@en .

fis:OptionsExchange a owl:Class ;
    rdfs:subClassOf fis:TradingVenue ;
    rdfs:label "Options Exchange"@en .

fis:OverTheCounterMarket a owl:Class ;
    rdfs:subClassOf fis:TradingVenue ;
    rdfs:label "Over-The-Counter Market"@en .

#################################################################
#    Securities and Cash Instruments Hierarchy
#################################################################

fis:Security a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument, fis:Asset ;
    rdfs:label "Security"@en ;
    rdfs:comment "A tradable financial asset representing a claim on an issuer. Sources conflict regarding the scope of the term: under US regulatory law it encompasses debt, equity, and derivatives; in the UK and international accounting contexts (e.g. IAS 32/39), derivatives are distinguished as a separate category of financial instrument from transferable securities."@en .

fis:DebtSecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Debt Security"@en, "Fixed Income Instrument"@en ;
    rdfs:comment "A negotiable financial instrument serving as evidence of a promise on the part of the issuer to make payments of principal and/or interest to the holder on specified dates."@en .

fis:EquitySecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Equity Security"@en, "Share"@en, "Stock"@en ;
    rdfs:comment "A negotiable financial instrument representing an equity ownership stake and residual claim on the assets of the issuer after all creditors have been satisfied."@en .

fis:HybridSecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Hybrid Security"@en ;
    rdfs:comment "A security combining characteristics of both debt securities and equity securities."@en .

fis:InvestmentFund a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Investment Fund"@en, "Pooled Investment"@en ;
    rdfs:comment "A security representing an indirect, proportional interest in a pooled portfolio of securities managed by an investment company."@en .

#################################################################
#    Debt Security Families and Specializations
#################################################################

fis:Bond a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "Bond"@en ;
    rdfs:comment "A debt security under which the issuer owes the holder a debt and is obliged to repay principal at maturity and usually periodic interest payments."@en .

fis:Debenture a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "Debenture"@en ;
    rdfs:comment "An unsecured debt security with a general claim on corporate assets, typically carrying a long maturity of ten years or more."@en .

fis:CommercialPaper a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:DebtSecurity
            [ a owl:Restriction ; owl:onProperty fis:hasMaturityTermInDays ; owl:someValuesFrom [ a rdfs:Datatype ; owl:onDatatype xsd:integer ; owl:withRestrictions ( [ xsd:maxInclusive 270 ] ) ] ]
        )
    ] ;
    rdfs:label "Commercial Paper"@en ;
    rdfs:comment "A short-term unsecured debt instrument issued by corporations to finance short-term obligations, maturing in not more than 270 days."@en .

fis:CertificateOfDeposit a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "Certificate of Deposit"@en ;
    rdfs:comment "A time deposit debt instrument issued by banks and depository institutions for a specified term."@en .

fis:CorporateBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Bond
            [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ]
        )
    ] ;
    rdfs:label "Corporate Bond"@en .

fis:GovernmentBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Bond
            [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ]
        )
    ] ;
    rdfs:label "Government Bond"@en, "Sovereign Bond"@en, "Treasury Bond"@en .

fis:MunicipalBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Bond
            [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:LocalGovernment ]
        )
    ] ;
    rdfs:label "Municipal Bond"@en, "Local Authority Bond"@en .

fis:SupranationalBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Bond
            [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SupranationalOrganization ]
        )
    ] ;
    rdfs:label "Supranational Bond"@en .

fis:CallableBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Bond
            [ a owl:Restriction ; owl:onProperty fis:hasEmbeddedOption ; owl:someValuesFrom fis:CallOption ]
        )
    ] ;
    rdfs:label "Callable Bond"@en .

fis:PutableBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Bond
            [ a owl:Restriction ; owl:onProperty fis:hasEmbeddedOption ; owl:someValuesFrom fis:PutOption ]
        )
    ] ;
    rdfs:label "Putable Bond"@en, "Retractable Bond"@en .

fis:ConvertibleBond a owl:Class ;
    rdfs:subClassOf fis:Bond, fis:HybridSecurity ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Bond
            fis:HybridSecurity
            [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:CommonStock ]
        )
    ] ;
    rdfs:label "Convertible Bond"@en .

fis:ZeroCouponBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Bond
            [ a owl:Restriction ; owl:onProperty fis:hasCouponRate ; owl:hasValue 0.0 ]
        )
    ] ;
    rdfs:label "Zero-Coupon Bond"@en, "Discount Bond"@en .

fis:PerpetualBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Perpetual Bond"@en, "Consol"@en, "Perpetuity"@en ;
    rdfs:comment "A bond with no defined maturity date that pays interest indefinitely."@en .

fis:FixedRateBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Fixed Rate Bond"@en .

fis:FloatingRateBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Floating Rate Bond"@en, "Floating Rate Note"@en .

fis:InflationIndexedBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Inflation-Indexed Bond"@en, "Linker"@en .

fis:SerialBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Serial Bond"@en .

fis:CoveredBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Covered Bond"@en .

fis:AssetBackedSecurity a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "Asset-Backed Security"@en .

fis:MortgagePool a owl:Class ;
    rdfs:subClassOf fis:Asset ;
    rdfs:label "Mortgage Pool"@en .

fis:MortgageBackedSecurity a owl:Class ;
    rdfs:subClassOf fis:AssetBackedSecurity ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:AssetBackedSecurity
            [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:MortgagePool ]
        )
    ] ;
    rdfs:label "Mortgage-Backed Security"@en .

fis:ResidentialMortgageBackedSecurity a owl:Class ;
    rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "Residential Mortgage-Backed Security"@en .

fis:CommercialMortgageBackedSecurity a owl:Class ;
    rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "Commercial Mortgage-Backed Security"@en .

fis:CollateralizedMortgageObligation a owl:Class ;
    rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "Collateralized Mortgage Obligation"@en, "Pay-Through Bond"@en .

fis:StrippedMortgageBackedSecurity a owl:Class ;
    rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "Stripped Mortgage-Backed Security"@en .

fis:CollateralizedDebtObligation a owl:Class ;
    rdfs:subClassOf fis:AssetBackedSecurity ;
    rdfs:label "Collateralized Debt Obligation"@en .

#################################################################
#    Equity Securities Hierarchy
#################################################################

fis:CommonStock a owl:Class ;
    rdfs:subClassOf fis:EquitySecurity ;
    rdfs:label "Common Stock"@en, "Ordinary Share"@en, "Equity Share"@en, "Voting Share"@en ;
    rdfs:comment "A form of corporate equity ownership conferring voting rights and residual claim on liquidation and profits."@en .

fis:PreferredStock a owl:Class ;
    rdfs:subClassOf fis:EquitySecurity, fis:HybridSecurity ;
    rdfs:label "Preferred Stock"@en, "Preference Share"@en ;
    rdfs:comment "A hybrid equity instrument senior to common stock in dividend claims and liquidation proceeds, typically without voting rights."@en .

fis:CumulativePreferredStock a owl:Class ;
    rdfs:subClassOf fis:PreferredStock ;
    rdfs:label "Cumulative Preferred Stock"@en .

fis:NonCumulativePreferredStock a owl:Class ;
    rdfs:subClassOf fis:PreferredStock ;
    rdfs:label "Non-Cumulative Preferred Stock"@en, "Straight Preferred Stock"@en .

fis:ConvertiblePreferredStock a owl:Class ;
    rdfs:subClassOf fis:PreferredStock ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:PreferredStock
            [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:CommonStock ]
        )
    ] ;
    rdfs:label "Convertible Preferred Stock"@en, "Convertible Preference Share"@en .

fis:DepositaryReceipt a owl:Class ;
    rdfs:subClassOf fis:EquitySecurity ;
    rdfs:label "Depositary Receipt"@en .

fis:AmericanDepositaryReceipt a owl:Class ;
    rdfs:subClassOf fis:DepositaryReceipt ;
    rdfs:label "American Depositary Receipt"@en .

#################################################################
#    Investment Funds Hierarchy
#################################################################

fis:MutualFund a owl:Class ;
    rdfs:subClassOf fis:InvestmentFund ;
    rdfs:label "Mutual Fund"@en, "Open-Ended Investment Company"@en .

fis:OpenEndFund a owl:Class ;
    rdfs:subClassOf fis:MutualFund ;
    rdfs:label "Open-End Fund"@en .

fis:ClosedEndFund a owl:Class ;
    rdfs:subClassOf fis:MutualFund ;
    rdfs:label "Closed-End Fund"@en .

fis:UnitInvestmentTrust a owl:Class ;
    rdfs:subClassOf fis:MutualFund ;
    rdfs:label "Unit Investment Trust"@en .

fis:ExchangeTradedFund a owl:Class ;
    rdfs:subClassOf fis:InvestmentFund ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:InvestmentFund
            [ a owl:Restriction ; owl:onProperty fis:hasTradingVenue ; owl:someValuesFrom fis:StockExchange ]
        )
    ] ;
    rdfs:label "Exchange-Traded Fund"@en .

fis:IndexExchangeTradedFund a owl:Class ;
    rdfs:subClassOf fis:ExchangeTradedFund ;
    rdfs:label "Index Exchange-Traded Fund"@en .

fis:LeveragedExchangeTradedFund a owl:Class ;
    rdfs:subClassOf fis:ExchangeTradedFund ;
    rdfs:label "Leveraged Exchange-Traded Fund"@en .

fis:InverseExchangeTradedFund a owl:Class ;
    rdfs:subClassOf fis:ExchangeTradedFund ;
    rdfs:label "Inverse Exchange-Traded Fund"@en .

#################################################################
#    Derivatives Hierarchy
#################################################################

fis:Derivative a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:label "Derivative"@en, "Derivative Contract"@en, "Derivative Instrument"@en ;
    rdfs:comment "A financial contract whose value is derived from the value and characteristics of one or more underlying entities such as an asset, index, rate, or event."@en .

fis:Forward a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Derivative
            [ a owl:Restriction ; owl:onProperty fis:hasTradingVenue ; owl:someValuesFrom fis:OverTheCounterMarket ]
        )
    ] ;
    rdfs:label "Forward"@en, "Forward Contract"@en ;
    rdfs:comment "A customized bilateral over-the-counter contract to buy or sell an asset at a predetermined price on a future date."@en .

fis:ForwardRateAgreement a owl:Class ;
    rdfs:subClassOf fis:Forward ;
    rdfs:label "Forward Rate Agreement"@en .

fis:Future a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Derivative
            [ a owl:Restriction ; owl:onProperty fis:hasTradingVenue ; owl:someValuesFrom fis:FuturesExchange ]
        )
    ] ;
    rdfs:label "Future"@en, "Futures Contract"@en ;
    rdfs:comment "A standardized contract traded on a futures exchange to buy or sell an underlying asset at a predetermined price on a specified delivery date."@en .

fis:StockFuture a owl:Class ;
    rdfs:subClassOf fis:Future ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Future
            [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom [ a owl:Class ; owl:unionOf ( fis:CommonStock fis:StockIndex ) ] ]
        )
    ] ;
    rdfs:label "Stock Future"@en .

fis:Option a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "Option"@en, "Option Contract"@en ;
    rdfs:comment "A financial contract conveying the right, but not the obligation, to buy or sell an underlying asset at a specified strike price on or before a specified date."@en .

fis:CallOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Call Option"@en ;
    rdfs:comment "An option conveying the right to buy the underlying asset at the strike price."@en .

fis:PutOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Put Option"@en ;
    rdfs:comment "An option conveying the right to sell the underlying asset at the strike price."@en .

fis:AmericanOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "American Option"@en ;
    rdfs:comment "An option that can be exercised on any trading day on or before its expiration date."@en .

fis:EuropeanOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "European Option"@en ;
    rdfs:comment "An option that can be exercised only on its expiration date."@en .

fis:BermudanOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Bermudan Option"@en .

fis:BinaryOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Binary Option"@en .

fis:BarrierOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Barrier Option"@en .

fis:StockOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Option
            [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:CommonStock ]
        )
    ] ;
    rdfs:label "Stock Option"@en .

fis:EquityWarrant a owl:Class ;
    rdfs:subClassOf fis:Option, fis:HybridSecurity ;
    rdfs:label "Equity Warrant"@en, "Warrant"@en ;
    rdfs:comment "A long-dated option issued by a company allowing the holder to purchase shares directly from the company at a specified price."@en .

fis:Swap a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "Swap"@en ;
    rdfs:comment "A contract in which counterparties exchange streams of cash flows calculated on a notional principal over a specified duration."@en .

fis:InterestRateSwap a owl:Class ;
    rdfs:subClassOf fis:Swap ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Swap
            [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:InterestRate ]
        )
    ] ;
    rdfs:label "Interest Rate Swap"@en .

fis:CurrencySwap a owl:Class ;
    rdfs:subClassOf fis:Swap ;
    rdfs:label "Currency Swap"@en .

fis:CreditDerivative a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "Credit Derivative"@en .

fis:CreditDefaultSwap a owl:Class ;
    rdfs:subClassOf fis:Swap, fis:CreditDerivative ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Swap
            fis:CreditDerivative
            [ a owl:Restriction ; owl:onProperty fis:hasReferenceEntity ; owl:someValuesFrom fis:LegalEntity ]
        )
    ] ;
    rdfs:label "Credit Default Swap"@en .

#################################################################
#    Disjointness Axioms
#################################################################

[] a owl:AllDisjointClasses ;
    owl:members (
        fis:CorporateBond
        fis:GovernmentBond
        fis:MunicipalBond
        fis:SupranationalBond
    ) .

[] a owl:AllDisjointClasses ;
    owl:members (
        fis:OpenEndFund
        fis:ClosedEndFund
        fis:UnitInvestmentTrust
    ) .

fis:CallOption owl:disjointWith fis:PutOption .

fis:AmericanOption owl:disjointWith fis:EuropeanOption .

fis:Forward owl:disjointWith fis:Future .

fis:CommonStock owl:disjointWith fis:PreferredStock .

fis:RetailInvestor owl:disjointWith fis:InstitutionalInvestor .
